{
  "cards": [
    {
      "pick": 0,
      "name_zh": "冰底焰",
      "concept": "利用敵人身下的冰面，綻放環形的火焰傷害並摧毀周圍可破壞的物件。",
      "cast_flavor": "法杖輕點，凍結的地表裂開細紋，赤紅的光自縫隙中湧出，將四周的碎石燒成灰燼。",
      "wish_zh": "你想要把敵人凍在火裡——這招讓火焰在冰面上綻放，同時摧毀周遭的一切阻礙。"
    },
    {
      "pick": 1,
      "name_zh": "灼寒引",
      "concept": "對站在冰面上的敵方造成單體火焰傷害並將其拉近，施放後自身陷入暈眩。",
      "cast_flavor": "一道熾熱的鎖鏈貫穿寒冰，將目標猛力拽向身前，而你的雙臂因反噬而短暫僵硬。",
      "wish_zh": "你想要把敵人凍在火裡——這招以火焰灼燒冰面之敵並將其拉近，代價是自身的短暫失神。"
    },
    {
      "pick": 3,
      "name_zh": "奪益環",
      "concept": "在距離二格處生成冰面，奪取敵方增益施加於自身，若目標孤立則造成火焰傷害。",
      "cast_flavor": "法杖劃過空氣，一圈結晶地面在遠處凝固，你吸走了對手身上的光芒，孤立的敵人身上燃起小火苗。",
      "wish_zh": "你想要把敵人凍在火裡——這招鋪設冰面並奪取增益，若敵人孤立無援，火焰將燒向他們。"
    }
  ]
}

